mapper.select:
select rr.dept_id, sum(num) as consumableNum, sum(sd.amount) as amount from consumable_reduce_record rr left join consumable_stock_detail sd on rr.id = sd.stock_id and sd.stock_flag = 'REDUCE' where rr.business_type = 'APPROVE' and rr.status='PASS'
and rr.reduce_date >= #{param.period.begin} and rr.reduce_date < #{param.period.end}
and rr.dept_id = #{param.deptId}
and rr.store_id = #{param.storeId}
GROUP BY rr.dept_id

select rr.dept_id,c.name,c.code,c.category_id,rr.store_id,c.brand,c.model,c.unit,rr.reduce_date,sd.num,sd.amount
from consumable_reduce_record rr
left join consumable_stock_detail sd on rr.id = sd.stock_id and sd.stock_flag = 'REDUCE'
left join consumable c on sd.consumable_id = c.id
where rr.business_type = 'APPROVE'
and rr.status='PASS'

    and rr.reduce_date >= #{param.period.begin} and rr.reduce_date < #{param.period.end}


    and rr.dept_id = #{param.deptId}


    and rr.store_id = #{param.storeId}

select a.id, `store_id`, `dept_id`, `claimant`, reduce_date, handler, remark, business_type, a.STATUS, depository_numbers, a.create_time, process_instance_id from consumable_reduce_record a inner join consumable_stock_detail b on a.id=b.stock_id inner join consumable c on b.consumable_id=c.id
a.store_id=#{param.storeId}
and a.status=#{param.status}
and a.reduce_date=#{param.claimantDate}
and a.dept_id=#{param.deptId}
and ( a.depository_numbers like concat("%",#{param.keyword},"%") or c.name like concat("%",#{param.keyword},"%"))
group by a.id order by reduce_date desc,a.create_time desc
